6: /// <summary>
7: /// TR-MCP-USECASE-018 (AC-006), TR-MCP-USECASE-019 (AC-008): finds platform dependence in unit test classes.
8: /// A test that depends on the platform is an integration test (operator 2026-10-19: "If it depends on the
9: /// environment, it's an integration test."), so an operating-system check, an OS-platform attribute, an
10: /// xUnit skip, or a binding to the real process host is a finding unless its test class (or an enclosing
11: /// class) carries <c>[Trait("Category", "Integration")]</c>. Strings and comments are ignored. Test classes
12: /// are types whose name ends in <c>Tests</c> or that declare <c>[Fact]</c> or <c>[Theory]</c> methods; other
13: /// helper types (for example the host-neutral <c>UnitTestPaths</c> fixture) are not test classes.
14: /// </summary>
15: internal static class UnitSuitePlatformScanner
16: {
17:     private static readonly (string Kind, Regex Pattern)[] Rules =
18:     [
19:         ("os-check", new Regex(@"\bOperatingSystem\s*\.\s*Is[A-Z]\w*\s*\(", RegexOptions.CultureInvariant)),
20:         ("os-check", new Regex(@"\bRuntimeInformation\s*\.\s*IsOSPlatform\s*\(", RegexOptions.CultureInvariant)),
21:         ("os-attribute", new Regex(@"\[\s*(?:[\w.]+\.)?(?:Supported|Unsupported)OSPlatform(?:Attribute)?\s*\(", RegexOptions.CultureInvariant)),
22:         ("skip", new Regex(@"\bAssert\s*\.\s*Skip(?:When|Unless)?\s*\(|\bSkipException\b|\bSkippable(?:Fact|Theory)\b|\[\s*(?:Fact|Theory)\s*\([^\]]*\bSkip\s*=", RegexOptions.CultureInvariant)),
23:         ("process-host", new Regex(@"\bSystemWorkspaceHostEnvironment\s*\.\s*Instance\b|\bWorkspacePathNormalizer\s*\.\s*Process\b", RegexOptions.CultureInvariant)),
24:     ];
25: 
26:     private static readonly Regex TypeDeclaration = new(
27:         @"\b(?:class|record|struct|interface)\s+([A-Za-z_]\w*)",
28:         RegexOptions.CultureInvariant);
29: 
30:     private static readonly Regex IntegrationTrait = new(
31:         @"\[\s*(?:Xunit\.)?Trait(?:Attribute)?\s*\(\s*""Category""\s*,\s*""Integration""\s*\)",
32:         RegexOptions.CultureInvariant);
33: 
34:     private static readonly Regex TestAttribute = new(@"\[\s*(?:Xunit\.)?(?:Fact|Theory)\b", RegexOptions.CultureInvariant);
35: 
36:     /// <summary>Scans one C# source file and returns its findings in line order.</summary>
37:     /// <param name="relativePath">Path reported with each finding.</param>
38:     /// <param name="source">File text.</param>
39:     internal static IReadOnlyList<UnitSuitePlatformFinding> Scan(string relativePath, string source)
40:     {
41:         ArgumentNullException.ThrowIfNull(relativePath);
42:         ArgumentNullException.ThrowIfNull(source);
43:         var original = source.Replace("\r\n", "\n", StringComparison.Ordinal).Split('\n');
44:         var code = StripCommentsAndStrings(source).Replace("\r\n", "\n", StringComparison.Ordinal).Split('\n');
45: 
46:         var open = new Stack<TypeScope>();
47:         var hits = new List<(int Line, string Kind, TypeScope? Owner)>();
48:         var attributeHits = new List<(int Line, string Kind)>();
49:         TypeScope? pending = null;
50:         var depth = 0;
51: 
52:         for (var i = 0; i < code.Length; i++)
53:         {
54:             var line = code[i];
55:             var trimmed = line.Trim();
56:             var declaration = TypeDeclaration.Match(line);
57:             if (declaration.Success)
58:             {
59:                 pending = new TypeScope(
60:                     declaration.Groups[1].Value,
61:                     HasIntegrationTrait(original, code, i),
62:                     open.Count > 0 ? open.Peek() : null,
63:                     depth);
64:             }
65: 
66:             if (open.Count > 0 && TestAttribute.IsMatch(line))
67:                 open.Peek().HasTests = true;
68: 
69:             var lineHits = Rules.Where(rule => rule.Pattern.IsMatch(line)).Select(rule => rule.Kind).ToList();
70:             if (!declaration.Success && trimmed.StartsWith('['))
71:             {
72:                 // Attribute lines belong to the type or member declared after them.
73:                 attributeHits.AddRange(lineHits.Select(kind => (i + 1, kind)));
74:             }
75:             else
76:             {
77:                 if (trimmed.Length > 0)
78:                 {
79:                     var target = declaration.Success ? pending : (open.Count > 0 ? open.Peek() : null);
80:                     hits.AddRange(attributeHits.Select(hit => (hit.Line, hit.Kind, target)));
81:                     attributeHits.Clear();
82:                 }
83: 
84:                 hits.AddRange(lineHits.Select(kind => (i + 1, kind, pending ?? (open.Count > 0 ? open.Peek() : null))));
85:             }
86: 
87:             foreach (var ch in line)
88:             {
89:                 if (ch == '{')
90:                 {
91:                     depth++;
92:                     if (pending is not null)
93:                     {
94:                         pending.Depth = depth;
95:                         open.Push(pending);
96:                         pending = null;
97:                     }
98:                 }
99:                 else if (ch == '}')
100:                 {
101:                     while (open.Count > 0 && open.Peek().Depth >= depth)
102:                         open.Pop();
103:                     depth--;
104:                 }
105:                 else if (ch == ';' && pending is not null && depth == pending.DeclaredDepth)
106:                 {
107:                     // A positional record or a declaration without a body ends here.
108:                     pending = null;
109:                 }
110:             }
111:         }
112: 
113:         var findings = new List<UnitSuitePlatformFinding>();
114:         foreach (var (line, kind, owner) in hits)
115:         {
116:             var testClass = owner;
117:             while (testClass is not null && !testClass.IsTestClass)
118:                 testClass = testClass.Parent;
119:             if (testClass is null || testClass.IsIntegration)
120:                 continue;
121:             findings.Add(new UnitSuitePlatformFinding(relativePath, line, kind, testClass.Name));
122:         }
123: 
124:         return findings;
125:     }
