127:     /// <summary>
128:     /// Replaces the contents of comments, string literals (regular, verbatim, interpolated, raw) and character
129:     /// literals with spaces, keeping every newline so line numbers stay the same.
130:     /// </summary>
131:     /// <param name="source">C# source text.</param>
132:     internal static string StripCommentsAndStrings(string source)
133:     {
134:         ArgumentNullException.ThrowIfNull(source);
135:         var result = new StringBuilder(source.Length);
136:         var i = 0;
137:         while (i < source.Length)
138:         {
139:             var c = source[i];
140:             var next = i + 1 < source.Length ? source[i + 1] : '\0';
141:             if (c == '/' && next == '/')
142:             {
143:                 while (i < source.Length && source[i] != '\n')
144:                     Blank(result, source[i++]);
145:             }
146:             else if (c == '/' && next == '*')
147:             {
148:                 Blank(result, source[i++]);
149:                 Blank(result, source[i++]);
150:                 while (i < source.Length && !(source[i] == '*' && i + 1 < source.Length && source[i + 1] == '/'))
151:                     Blank(result, source[i++]);
152:                 if (i < source.Length)
153:                 {
154:                     Blank(result, source[i++]);
155:                     Blank(result, source[i++]);
156:                 }
157:             }
158:             else if (c == '"' || ((c == '@' || c == '$') && (next == '"' || next == '@' || next == '$')))
159:             {
160:                 var verbatim = false;
161:                 while (i < source.Length && source[i] != '"')
162:                 {
163:                     verbatim |= source[i] == '@';
164:                     result.Append(source[i++]);
165:                 }
166: 
167:                 var quotes = 0;
168:                 while (i + quotes < source.Length && source[i + quotes] == '"')
169:                     quotes++;
170:                 if (quotes >= 3)
171:                 {
172:                     for (var q = 0; q < quotes; q++)
173:                         result.Append(source[i++]);
174:                     while (i < source.Length && !IsQuoteRun(source, i, quotes))
175:                         Blank(result, source[i++]);
176:                     for (var q = 0; q < quotes && i < source.Length; q++)
177:                         result.Append(source[i++]);
178:                 }
179:                 else
180:                 {
181:                     result.Append(source[i++]);
182:                     while (i < source.Length)
183:                     {
184:                         if (verbatim && source[i] == '"' && i + 1 < source.Length && source[i + 1] == '"')
185:                         {
186:                             Blank(result, source[i++]);
187:                             Blank(result, source[i++]);
188:                         }
189:                         else if (!verbatim && source[i] == '\\' && i + 1 < source.Length)
190:                         {
191:                             Blank(result, source[i++]);
192:                             Blank(result, source[i++]);
193:                         }
194:                         else if (source[i] == '"' || (!verbatim && source[i] == '\n'))
195:                         {
196:                             break;
197:                         }
198:                         else
199:                         {
200:                             Blank(result, source[i++]);
201:                         }
202:                     }
203: 
204:                     if (i < source.Length && source[i] == '"')
205:                         result.Append(source[i++]);
206:                 }
207:             }
208:             else if (c == '\'')
209:             {
210:                 result.Append(source[i++]);
211:                 while (i < source.Length && source[i] != '\'' && source[i] != '\n')
212:                 {
213:                     if (source[i] == '\\' && i + 1 < source.Length)
214:                         Blank(result, source[i++]);
215:                     Blank(result, source[i++]);
216:                 }
217: 
218:                 if (i < source.Length && source[i] == '\'')
219:                     result.Append(source[i++]);
220:             }
221:             else
222:             {
223:                 result.Append(source[i++]);
224:             }
225:         }
226: 
227:         return result.ToString();
228:     }
229: 
230:     private static void Blank(StringBuilder result, char c) => result.Append(c == '\n' ? '\n' : ' ');
231: 
232:     private static bool IsQuoteRun(string source, int index, int count)
233:     {
234:         for (var q = 0; q < count; q++)
235:         {
236:             if (index + q >= source.Length || source[index + q] != '"')
237:                 return false;
238:         }
239: 
240:         return true;
241:     }
242: 
243:     private static bool HasIntegrationTrait(string[] original, string[] code, int declarationLine)
244:     {
245:         if (IntegrationTrait.IsMatch(original[declarationLine]))
246:             return true;
247:         for (var i = declarationLine - 1; i >= 0; i--)
248:         {
249:             var stripped = code[i].Trim();
250:             if (stripped.Length == 0)
251:                 continue;
252:             if (!stripped.StartsWith('[') && !stripped.EndsWith(']') && !stripped.EndsWith(','))
253:                 break;
254:             if (IntegrationTrait.IsMatch(original[i]))
255:                 return true;
256:         }
257: 
258:         return false;
259:     }
260: 
261:     private sealed class TypeScope(string name, bool hasIntegrationTrait, TypeScope? parent, int declaredDepth)
262:     {
263:         internal string Name { get; } = name;
264: 
265:         internal TypeScope? Parent { get; } = parent;
266: 
267:         internal int DeclaredDepth { get; } = declaredDepth;
268: 
269:         internal int Depth { get; set; } = -1;
270: 
271:         internal bool HasTests { get; set; }
272: 
273:         internal bool IsTestClass => HasTests || Name.EndsWith("Tests", StringComparison.Ordinal);
274: 
275:         internal bool IsIntegration => hasIntegrationTrait || (Parent?.IsIntegration ?? false);
276:     }
277: }
