11: {
12:     private static readonly string[] ExpectedUnitProjects =
13:     [
14:         "QBrainAi.Client.Tests",
15:         "QBrainAi.Cqrs.Tests",
16:         "QBrainAi.Launcher.Tests",
17:         "QBrainAi.McpAgent.Tests",
