23:     /// <summary>No unit test class in the unit-suite projects depends on the platform.</summary>
24:     [Fact]
25:     public void UnitTestClasses_HaveNoPlatformDependence()
26:     {
27:         var testsRoot = FindTestsRoot();
28:         var findings = UnitProjects(testsRoot)
29:             .SelectMany(project => Directory.EnumerateFiles(project, "*.cs", SearchOption.AllDirectories))
30:             .Where(path => !IsBuildOutput(path))
31:             .OrderBy(path => path, StringComparer.Ordinal)
32:             .SelectMany(path => UnitSuitePlatformScanner.Scan(
33:                 Path.GetRelativePath(testsRoot, path).Replace('\\', '/'),
34:                 File.ReadAllText(path)))
35:             .Select(finding => finding.ToString())
36:             .ToArray();
37: 
38:         Assert.True(
39:             findings.Length == 0,
40:             "A test that depends on the platform is an integration test: tag its class [Trait(\"Category\", \"Integration\")] "
41:             + "(with [Trait(\"Platform\", ...)] when it applies to one host) or remove the dependence. Findings:"
42:             + Environment.NewLine + string.Join(Environment.NewLine, findings));
43:     }
