56:     private static IEnumerable<string> UnitProjects(string testsRoot) =>
57:         Directory.EnumerateDirectories(testsRoot)
58:             .Where(directory =>
59:             {
60:                 var name = new DirectoryInfo(directory).Name;
61:                 return name.EndsWith(".Tests", StringComparison.Ordinal)
62:                     && !name.Contains("IntegrationTests", StringComparison.Ordinal)
63:                     && !name.Contains("PluginIntegration", StringComparison.Ordinal)
64:                     && !name.Contains("Review.Tests", StringComparison.Ordinal)
65:                     && !name.EndsWith("Build.Tests", StringComparison.Ordinal)
66:                     && Directory.EnumerateFiles(directory, "*.csproj").Any();
67:             });
