69:     private static bool IsBuildOutput(string path)
70:     {
71:         var separator = Path.DirectorySeparatorChar;
72:         return path.Contains($"{separator}bin{separator}", StringComparison.OrdinalIgnoreCase)
73:             || path.Contains($"{separator}obj{separator}", StringComparison.OrdinalIgnoreCase);
